:root { font-family: system-ui, sans-serif; color: #202c3e; background: #f4f6f9; }
body { margin: 0; }
main { max-width: 760px; margin: 3rem auto; padding: 2rem; background: white; border-radius: 12px; }
h1 { margin-top: 1rem; }
form { display: flex; flex-wrap: wrap; gap: .75rem; align-items: center; margin-bottom: 1.5rem; }
label { font-weight: 600; }
input { flex: 1; min-width: 160px; border: 1px solid #778397; border-radius: 5px; padding: .65rem; font: inherit; }
button { border: 0; border-radius: 5px; background: #2456a8; color: white; padding: .7rem 1rem; font: inherit; cursor: pointer; }
button:disabled { opacity: .6; cursor: wait; }
button:hover:not(:disabled) { background: #193f7e; }
:focus-visible { outline: 3px solid #c07800; outline-offset: 3px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 1rem 0; border-bottom: 1px solid #d8dee8; }
.project-row span { overflow-wrap: anywhere; }
[role="alert"] { color: #a11b1b; }
@media (max-width: 600px) { main { margin: 1rem; padding: 1rem; } }

