import { fileURLToPath } from 'node:url';
import { DatabaseSync } from 'node:sqlite';

const root = dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || join(root, 'data', 'workboard.sqlite');
mkdirSync(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  );
`);
const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY id');
const getProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');

function json(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 64 * 1024) {
      const error = new Error('Request is too large');
      error.status = 413;
      throw error;
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    const error = new Error('Invalid JSON');
    error.status = 400;
    throw error;
  }
}

const assets = {
  '/app.js': ['app.js', 'text/javascript; charset=utf-8'],
  '/styles.css': ['styles.css', 'text/css; charset=utf-8'],
};

const server = createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && path === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (path === '/api/projects' && request.method === 'GET') {
      return json(response, 200, listProjects.all());
    }
    if (path === '/api/projects' && request.method === 'POST') {
      const input = await readJson(request);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return json(response, 201, getProject.get(Number(result.lastInsertRowid)));
    }
    const projectMatch = path.match(/^\/api\/projects\/(\d+)$/);
    if (request.method === 'GET' && projectMatch) {
      const project = getProject.get(Number(projectMatch[1]));
      return project
        ? json(response, 200, project)
        : json(response, 404, { error: 'Project not found' });
    }
    if (request.method === 'GET') {
      const asset = assets[path];
      if (asset || path === '/' || /^\/projects\/\d+$/.test(path)) {
        const [file, type] = asset || ['index.html', 'text/html; charset=utf-8'];
        const content = await readFile(join(root, 'public', file));
        response.writeHead(200, { 'Content-Type': type });
        return response.end(content);
      }
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (!error.status) console.error(error);
    if (!response.headersSent) {
      json(response, error.status || 500, { error: error.status ? error.message : 'Internal server error' });
    } else {
      response.end();
    }
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => {
    server.close(() => {
      db.close();
      process.exit(0);
    });
  });
}

const app = document.querySelector('#app');

async function api(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to load projects');
  return data;
}

function button(label, onClick) {
  const element = document.createElement('button');
  element.type = 'button';
  element.textContent = label;
  element.addEventListener('click', onClick);
  return element;
}

function navigate(path) {
  history.pushState(null, '', path);
  render();
}

function showError(container, error) {
  container.textContent = error.message;
  container.hidden = false;
}

let renderVersion = 0;
async function render() {
  const version = ++renderVersion;
  app.setAttribute('aria-busy', 'true');
  app.replaceChildren();
  const heading = document.createElement('h1');
  const alert = document.createElement('p');
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    app.append(button('Projects', () => navigate('/')), heading, alert);
    try {
      const project = await api(`/api/projects/${match[1]}`);
      if (version !== renderVersion) return;
      heading.textContent = project.name;
      document.title = `${project.name} · Workboard`;
    } catch (error) {
      if (version !== renderVersion) return;
      heading.textContent = 'Project unavailable';
      showError(alert, error);
    }
  } else {
    heading.textContent = 'Workboard';
    document.title = 'Workboard';
    const form = document.createElement('form');
    const label = document.createElement('label');
    label.htmlFor = 'project-name';
    label.textContent = 'Project name';
    const input = document.createElement('input');
    input.id = 'project-name';
    input.name = 'name';
    input.type = 'text';
    const submit = document.createElement('button');
    submit.type = 'submit';
    submit.textContent = 'Create project';
    form.append(label, input, submit);
    const list = document.createElement('div');
    list.setAttribute('aria-label', 'Projects');
    function addProject(project) {
      const row = document.createElement('div');
      row.className = 'project-row';
      row.dataset.testid = 'project-row';
      const name = document.createElement('span');
      name.textContent = project.name;
      row.append(name, button('Open project', () => navigate(`/projects/${project.id}`)));
      list.append(row);
    }
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      alert.hidden = true;
      if (!input.value.trim()) {
        showError(alert, new Error('Project name is required'));
        return;
      }
      submit.disabled = true;
      try {
        const project = await api('/api/projects', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name: input.value }),
        });
        if (version !== renderVersion) return;
        addProject(project);
        input.value = '';
        input.focus();
      } catch (error) {
        if (version === renderVersion) showError(alert, error);
      } finally {
        submit.disabled = false;
      }
    });
    app.append(heading, form, alert, list);
    // Do not allow a creation to race the initial list load.
    submit.disabled = true;
    try {
      const projects = await api('/api/projects');
      if (version !== renderVersion) return;
      projects.forEach(addProject);
    } catch (error) {
      if (version !== renderVersion) return;
      showError(alert, error);
    }
    submit.disabled = false;
  }
  app.setAttribute('aria-busy', 'false');
}

window.addEventListener('popstate', render);
render();

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { createServer } from 'node:net';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

async function availablePort() {
  const server = createServer();
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  const port = server.address().port;
  await new Promise((resolve) => server.close(resolve));
  return port;
}

test('projects validate, retain creation order, and persist across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const port = await availablePort();
  const base = `http://127.0.0.1:${port}`;
  let child;
  let output = '';
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'db.sqlite') },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    child.stdout.on('data', (chunk) => { output += chunk; });
    child.stderr.on('data', (chunk) => { output += chunk; });
    for (let attempt = 0; attempt < 100; attempt++) {
      try {
        const response = await fetch(`${base}/health`);
        if (response.ok) return;
      } catch {}
      if (child.exitCode !== null) throw new Error(output);
      await new Promise((resolve) => setTimeout(resolve, 30));
    }
    throw new Error(`Server did not start: ${output}`);
  }
  async function stop() {
    if (child && child.exitCode === null) {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    }
  }
  async function create(name) {
    return fetch(`${base}/api/projects`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
  }
  try {
    await start();
    const health = await fetch(`${base}/health`);
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    for (const name of ['', '  \n\t ']) {
      const response = await create(name);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Project name is required' });
    }
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), []);
    const firstResponse = await create('  First project  ');
    assert.equal(firstResponse.status, 201);
    const first = await firstResponse.json();
    assert.equal(first.name, 'First project');
    const second = await (await create('<script>literal name</script>')).json();
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [first, second]);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    for (const path of ['/', `/projects/${first.id}`]) {
      const response = await fetch(`${base}${path}`);
      assert.equal(response.status, 200);
      assert.match(await response.text(), /<title>Workboard<\/title>/);
    }
    assert.equal((await fetch(`${base}/api/projects/999999`)).status, 404);
    const malformed = await fetch(`${base}/api/projects`, { method: 'POST', body: '{' });
    assert.equal(malformed.status, 400);
    await stop();
    await start();
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [first, second]);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
  } finally {
    await stop();
    await rm(directory, { recursive: true, force: true });
  }
});

:root { font-family: system-ui, sans-serif; color: #202c3e; background: #f4f6f9; }
body { margin: 0; }
main { max-width: 760px; margin: 3rem auto; padding: 2rem; background: white; border-radius: 12px; }
h1 { margin-top: 1rem; }
form { display: flex; flex-wrap: wrap; gap: .75rem; align-items: center; margin-bottom: 1.5rem; }
label { font-weight: 600; }
input { flex: 1; min-width: 160px; border: 1px solid #778397; border-radius: 5px; padding: .65rem; font: inherit; }
button { border: 0; border-radius: 5px; background: #2456a8; color: white; padding: .7rem 1rem; font: inherit; cursor: pointer; }
button:disabled { opacity: .6; cursor: wait; }
button:hover:not(:disabled) { background: #193f7e; }
:focus-visible { outline: 3px solid #c07800; outline-offset: 3px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 1rem 0; border-bottom: 1px solid #d8dee8; }
.project-row span { overflow-wrap: anywhere; }
[role="alert"] { color: #a11b1b; }
@media (max-width: 600px) { main { margin: 1rem; padding: 1rem; } }

